import{_ as i,a as e,c as a,ac as o}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"Go：从终端到第一个程序","description":"Windows、macOS、Linux 的安装检查，理解目录、模块、源文件和程序，解决 go.mod file not found。","frontmatter":{"title":"Go：从终端到第一个程序","description":"Windows、macOS、Linux 的安装检查，理解目录、模块、源文件和程序，解决 go.mod file not found。","showdocs":{"topics":[{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"知识专题","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Go 实践课程","summary":"Windows、macOS、Linux 的安装检查，理解目录、模块、源文件和程序，解决 go.mod file not found。","status":"active","related":[{"title":"Beego 工程维护：模块、MVC 与排错","link":"/programming/go/plus/ecosystem/base-beego","kind":"开发实践","scope":"general","audience":"general"},{"title":"Go 编码规范：格式、命名、接口与评审","link":"/programming/go/plus/practice/coding_guidelines","kind":"开发实践","scope":"general","audience":"general"},{"title":"Go 定时任务：Timer、Ticker、cron 与退出","link":"/programming/go/plus/practice/scheduling","kind":"开发实践","scope":"general","audience":"general"},{"title":"Go 高级并发实践：有界执行、背压、失败取消与保序","link":"/programming/go/plus/practice/concurrency","kind":"开发实践","scope":"general","audience":"general"},{"title":"Go 工具链：环境、构建、测试与命令速查","link":"/programming/go/toolchain","kind":"排错","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Go 变量、类型与控制流","link":"/programming/go/base/basic/values"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Go 变量、类型与控制流","link":"/programming/go/base/basic/values"}},"headers":[],"relativePath":"programming/go/base/basic/start.md","filePath":"programming/go/base/basic/start.md"}'),n={name:"programming/go/base/basic/start.md"};function t(d,s,l,p,c,r){return e(),a("div",null,[...s[0]||(s[0]=[o(`<h1 id="go-从终端到第一个程序" tabindex="-1">Go：从终端到第一个程序 <a class="header-anchor" href="#go-从终端到第一个程序" aria-label="Permalink to &quot;Go：从终端到第一个程序&quot;">​</a></h1><p>从一个空目录开始，写一个打印学习进度的小程序。源码、包、模块和进程有各自的作用，弄清它们，也就能从首次运行的错误判断该检查哪一层。下文采用 Go 1.27.2。</p><h2 id="install" tabindex="-1">安装与 go version <a class="header-anchor" href="#install" aria-label="Permalink to &quot;安装与 go version {#install}&quot;">​</a></h2><p>从 <a href="https://go.dev/dl/" target="_blank" rel="noopener noreferrer">Go 官方下载页</a> 选择 1.27.2 和自己的系统、处理器架构。amd64 对应常见 Intel/AMD 64 位机器，arm64 对应 Apple Silicon 等 ARM 64 位机器；文件扩展名不是架构。安装前关闭旧终端，装完再新开终端，让 PATH 生效。PATH 是系统查找 <code>go</code> 可执行文件的一组目录。</p><table tabindex="0"><thead><tr><th>系统与终端</th><th>操作</th><th>检查</th></tr></thead><tbody><tr><td>Windows / PowerShell</td><td>运行 amd64 MSI 安装包，接受安装目录或记录自选目录</td><td><code>Get-Command go</code>，<code>go version</code></td></tr><tr><td>macOS / Zsh（平台说明）</td><td>Apple Silicon 选择 arm64 PKG，按安装器操作</td><td><code>command -v go</code>，<code>go version</code></td></tr><tr><td>Ubuntu / Bash</td><td>下载 amd64 tar.gz，与下载页 SHA-256 对照；解压到自己可写的独立目录</td><td><code>command -v go</code>，<code>go version</code></td></tr></tbody></table><p>Linux 不需要覆盖系统目录。以下在下载文件所在目录运行，<code>$PWD</code> 是当前目录；先确认 <code>go-course-toolchain</code> 尚不存在，再解压到这个新目录：</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> go1.27.2.linux-amd64.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> go-course-toolchain</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> go-course-toolchain</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> go1.27.2.linux-amd64.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/go-course-toolchain/go/bin:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span></code></pre></div><p>这次 <code>export</code> 只影响当前终端。新终端需要再次设置，或确认无误后把对应绝对目录加入自己的 Shell 配置。不要同时手动设置 GOROOT；普通安装由工具链自己确定标准库位置。预期版本输出包含 <code>go1.27.2</code>，平台分别为 <code>windows/amd64</code>、<code>darwin/arm64</code>、<code>linux/amd64</code>。<code>go env GOOS GOARCH</code> 可再确认目标平台。</p><h2 id="module" tabindex="-1">目录、文件与模块 <a class="header-anchor" href="#module" aria-label="Permalink to &quot;目录、文件与模块 {#module}&quot;">​</a></h2><p>终端执行命令时有一个“当前目录”。<code>pwd</code>/<code>Get-Location</code> 查看它，<code>cd</code> 改变它；相对路径从当前目录开始，绝对路径从盘符或根目录开始。空格路径需要引号，例如 PowerShell 的 <code>cd &#39;D:\\学习 Go&#39;</code>。<code>main.go</code> 是保存代码的 UTF-8 文本文件，不是要双击的程序。</p><p>在空目录中执行（PowerShell、Bash、Zsh 均适用）：</p><div class="language-sh vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> go-first</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> go-first</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example.com/go-first</span></span></code></pre></div><p>预期生成 <code>go.mod</code>。模块是这一组包及依赖的边界，<code>example.com/go-first</code> 是本地练习的模块名，不需要真的注册域名。一个目录里的普通 <code>.go</code> 文件通常属于同一个包；<code>package main</code> 表示可执行程序，<code>func main()</code> 是程序入口。已有示例目录包含 go.mod 时不要再次 init。</p><p>用编辑器在 go-first 中保存 <code>main.go</code>，完整内容如下：</p><div class="language-go vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">package</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fmt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">func</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Go&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    lessons </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    fmt.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你好，</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">；今天练习 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 次</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, name, lessons)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>保存后，在同一目录执行 <code>go fmt ./...</code> 整理格式，再执行 <code>go run .</code>。点号表示当前包。Go 工具读取包里的源文件和导入的依赖，把它们编译并链接成可执行文件，然后启动一个进程，由 <code>main</code> 包的 <code>main</code> 函数接手运行。模块路径帮助工具定位包；程序入口由包和函数的声明决定。</p><p>预期输出</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你好，Go；今天练习 3 次</span></span></code></pre></div><p>打印完后 <code>main</code> 返回，进程退出，终端再次等候命令。源文件仍在磁盘上。修改文件只改变下一次编译的输入，已经构建好的二进制仍执行旧逻辑。注释用 <code>//</code>，左花括号与 <code>func main()</code> 放在同一行。</p><p><code>import &quot;fmt&quot;</code> 引入标准库格式化包。<code>:=</code> 声明并初始化局部变量；<code>%s</code> 输出字符串，<code>%d</code> 输出整数，<code>\\n</code> 换行。字符串用双引号，中文引号不能替代代码引号。</p><h2 id="module-error" tabindex="-1">go.mod file not found 与首次运行排错 <a class="header-anchor" href="#module-error" aria-label="Permalink to &quot;go.mod file not found 与首次运行排错 {#module-error}&quot;">​</a></h2><p>看到 <code>go.mod file not found</code>，先查看当前目录是否有 go.mod；若刚建立空项目，执行上面的 init；若使用仓库示例，cd 到其模块目录。不要在磁盘根目录 init 来“修好”错误，那会把不相关文件放入同一模块。</p><p><code>go: command not found</code> 或 PowerShell “无法将 go 识别为…”：先检查安装与 PATH，再开新终端。<code>declared and not used</code>：局部变量声明后没有用，删除无用变量或把它用于结果。<code>imported and not used</code>：移除多余导入。<code>syntax error</code>：从报告的文件和行号开始，检查前一行的括号和引号；一次只改一个原因。</p><p>编译为可重复启动的文件：Windows 用 <code>go build -o first.exe .</code> 后 <code>./first.exe</code>；Bash/Zsh 用 <code>go build -o first .</code> 后 <code>./first</code>。<code>go build</code> 成功时通常没有输出；<code>go run</code> 的临时二进制不是你要分发的文件。</p><h2 id="exercise" tabindex="-1">练习与自检 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;练习与自检 {#exercise}&quot;">​</a></h2><p>把名字改成“学习者”，把次数改成 5。先预测输出，再运行；然后声明 <code>var done bool</code>，用 <code>%t</code> 输出它，验证没有初始化的布尔值。预期最后一个值是 false。进一步解释：源文件、编译后的程序和正在执行的进程分别是什么？</p><details class="details custom-block"><summary>参考解法</summary><p>将 <code>name := &quot;Go&quot;</code> 改为 <code>name := &quot;学习者&quot;</code>，<code>lessons := 3</code> 改为 <code>lessons := 5</code>。在 main 内增加 <code>var done bool</code> 和 <code>fmt.Printf(&quot;完成：%t\\n&quot;, done)</code>。第一行是“你好，学习者；今天练习 5 次”，第二行“完成：false”。变量的零值由类型决定；字符串为空串、数值为 0、布尔为 false。源文件是输入，二进制是编译输出，进程是一次运行中的实例。</p></details><p>学习顺序请使用本页底部的路线导航。查单条命令用 <a href="/programming/go/plus/ecosystem/commands">Go 工具链命令</a>。核对依据：<a href="https://go.dev/doc/install" target="_blank" rel="noopener noreferrer">官方安装步骤</a>、<a href="https://go.dev/doc/tutorial/getting-started" target="_blank" rel="noopener noreferrer">创建模块与首次运行</a>。</p>`,28)])])}const g=i(n,[["render",t]]);export{k as __pageData,g as default};
